from pickle import dump,load
def chercher(nom,chm):
    f=open(chm,"rb")
    trouve=False
    fin=False
    while not trouve and not fin:
        try:
            e=load(f)
            if e["nom"].upper().find(nom.upper())!=-1:
                print(nom,"est trouve son tel est:",e["tel"])
                trouve=True
        except:
            fin=True
    if not trouve:
        print(" nom inexistant !!!!!!")
    f.close()
            
        
    
    
